module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire not_sel0, not_sel1;
wire and0, and1, and2, and3;

// Invert select signals
not (not_sel0, sel[0]);
not (not_sel1, sel[1]);

// AND gates for each input
and (and0, in[0], not_sel0, not_sel1); // when sel = 00
and (and1, in[1], sel[0], not_sel1);   // when sel = 01
and (and2, in[2], not_sel0, sel[1]);   // when sel = 10
and (and3, in[3], sel[0], sel[1]);     // when sel = 11

// OR gate to combine the outputs of the AND gates
or (out, and0, and1, and2, and3);

endmodule

