module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    if (in[3]) 
        code = 2'b11; // MSB is 1
    else if (in[2]) 
        code = 2'b10; // Second MSB is 1
    else if (in[1]) 
        code = 2'b01; // Third MSB is 1
    else if (in[0]) 
        code = 2'b00; // LSB is 1
    else 
        code = 2'b00; // No bits are 1
end

endmodule

module priority_encoder (
    input [3:0] in,
