    else if (in[1]) 
        code = 2'b01; // Output for bit 1
    else if (in[0]) 
        code = 2'b00; // Output for bit 0
    else 
        code = 2'b00; // Default output when all bits are 0
end

endmodule

module fsm_3state (
    input clk, reset,
    output reg [1:0] state
);

    // State encoding
    parameter A = 2'b00, B = 2'b01, C = 2'b10;

    // Sequential logic for state transition
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= A; // Initialize to state A on reset
        end else begin
            case (state)
                A: state <= B;
                B: state <= C;
                C: state <= A;
                default: state <= A; // Default case for safety
            endcase
        end
    end

endmodule

