module traffic_light (
    input clk, reset,
    output [2:0] light
);

    reg [1:0] state, next_state;
    reg [3:0] timer; // Assuming a 4-bit timer for simplicity
    reg [2:0] light_reg;

    // State Encoding
    parameter RED = 2'b00, GREEN = 2'b01, YELLOW = 2'b10;

    // Light output
    assign light = light_reg;

    // State Transition Logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= RED;
            timer <= 4'b0000;
            light_reg <= 3'b001; // RED
        end else begin
            if (timer == 4'b1111) begin // Timer limit for state duration
                state <= next_state;
                timer <= 4'b0000; // Reset timer
            end else begin
                timer <= timer + 1; // Increment timer
            end
        end
    end

    // Next State Logic
    always @(*) begin
        case (state)
            RED: begin
                next_state = GREEN;
                light_reg = 3'b001; // RED
            end
            GREEN: begin
                next_state = YELLOW;
                light_reg = 3'b010; // GREEN
            end
            YELLOW: begin
                next_state = RED;
                light_reg = 3'b100; // YELLOW
            end
            default: begin
                next_state = RED;
                light_reg = 3'b001; // Default to RED
            end
        endcase
    end

endmodule

module traffic_light (
    input clk, reset,
    output reg [2:0] light
);

    reg [1:0] state;
    reg [3:0] counter; // 4-bit counter for timing

    parameter RED = 2'b00, GREEN = 2'b01, YELLOW = 2'b10;
    parameter RED_TIME = 4'd10, GREEN_TIME = 4'd5, YELLOW_TIME = 4'd2;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= RED;
            counter <= 0;
            light <= 3'b100; // RED
        end else begin
            if (counter == get_time(state)) begin
                counter <= 0;
                state <= next_state(state);
            end else begin
                counter <= counter + 1;
            end
            light <= get_light(state);
        end
    end

    function [3:0] get_time(input [1:0] state);
        case (state)
            RED: get_time = RED_TIME;
            GREEN: get_time = GREEN_TIME;
            YELLOW: get_time = YELLOW_TIME;
            default: get_time = 4'd0;
        endcase
    endfunction

    function [2:0] next_state(input [1:0] state);
        case (state)
            RED: next_state = GREEN;
            GREEN: next_state = YELLOW;
            YELLOW: next_state = RED;
            default: next_state = RED;
        endcase
    endfunction

    function [2:0] get_light(input [1:0] state);
        case (state)
            RED: get_light = 3'b100;
            GREEN: get_light = 3'b010;
            YELLOW: get_light = 3'b001;
            default: get_light = 3'b000;
        endcase
    endfunction

endmodule

module traffic_light (
    input clk, reset,
    output reg [2:0] light
);

    // State encoding
    parameter RED = 3'b001, YELLOW = 3'b010, GREEN = 3'b100;
    reg [2:0] state, next_state;

    // Timing parameters
    reg [3:0] timer; // 4-bit timer for simplicity
    parameter RED_TIME = 4'd10, YELLOW_TIME = 4'd3, GREEN_TIME = 4'd7;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= RED;
            timer <= 0;
        end else if (timer == 0) begin
            state <= next_state;
            timer <= (next_state == RED) ? RED_TIME :
                      (next_state == YELLOW) ? YELLOW_TIME : GREEN_TIME;
        end else begin
            timer <= timer - 1;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            RED: next_state = GREEN;
            GREEN: next_state = YELLOW;
            YELLOW: next_state = RED;
            default: next_state = RED; // Fallback case
        endcase
    end

    // Output logic
    always @(*) begin
        case (state)
            RED: light = 3'b001;
            GREEN: light = 3'b100;
            YELLOW: light = 3'b010;
            default: light = 3'b000; // Off state
        endcase
    end

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // State encoding
    parameter RED = 3'b001;
    parameter GREEN = 3'b010;
    parameter YELLOW = 3'b100;

    reg [2:0] current_state, next_state;
    reg [3:0] timer; // Timer to control state duration
    reg [2:0] light_reg;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= RED;
            timer <= 0;
        end else begin
            current_state <= next_state;
            if (timer < 4'd9) begin // Adjust timing as needed
                timer <= timer + 1;
            end else begin
                timer <= 0; // Reset timer after reaching limit
            end
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            RED: begin
                if (timer == 4'd9) // Time to transition to GREEN
                    next_state = GREEN;
                else
                    next_state = RED;
            end
            GREEN: begin
                if (timer == 4'd9) // Time to transition to YELLOW
                    next_state = YELLOW;
                else
                    next_state = GREEN;
            end
            YELLOW: begin
                if (timer == 4'd9) // Time to transition to RED
                    next_state = RED;
                else
                    next_state = YELLOW;
            end
            default: next_state = RED; // Fallback to RED
        endcase
    end

    // Output logic
    always @(*) begin
        case (current_state)
            RED: light_reg = RED;
            GREEN: light_reg = GREEN;
            YELLOW: light_reg = YELLOW;
            default: light_reg = RED; // Fallback to RED
        endcase
    end

    assign light = light_reg;

endmodule

module traffic_light (
    input clk, reset,
