module int_sqrt (
    input signed [15:0] in_0,
    output reg signed [7:0] out
);

reg signed [7:0] guess;
reg signed [7:0] next_guess;
reg [3:0] count;
reg valid;

always @(posedge valid or posedge in_0) begin
    if (in_0 < 0) begin
        out <= 0; // Undefined for negative input
        valid <= 0;
    end else if (in_0 == 0) begin
        out <= 0;
        valid <= 0;
    end else begin
        guess <= in_0[7:0]; // Start with initial guess
        count <= 0;
        valid <= 1;
    end
end

always @(posedge valid) begin
    if (count < 8) begin
        next_guess = (guess + in_0 / guess) >>> 1; // Newton-Raphson iteration
        if (next_guess == guess) begin
            out <= next_guess; // Converged
            valid <= 0;
        end else begin
            guess <= next_guess;
            count <= count + 1;
        end
    end else begin
        out <= guess; // Max iterations reached
        valid <= 0;
    end
end

endmodule

