    input signed [15:0] in_0,
    output reg signed [7:0] out
);

reg [7:0] guess;
reg [7:0] next_guess;
reg valid;
reg [3:0] count;

always @(posedge valid) begin
    if (in_0 < 0) begin
        out <= 8'sb0; // Handle negative input
    end else begin
        guess <= 8'd0; // Initial guess
        count <= 4'd0;
        valid <= 1'b1;
    end
end

always @(posedge valid) begin
    if (count < 4'd10) begin // Limit iterations to prevent infinite loop
        next_guess <= (guess + in_0 / guess) >> 1; // Newton-Raphson update
        if (next_guess == guess) begin
            out <= next_guess; // Converged
            valid <= 1'b0; // Stop iterations
        end else begin
            guess <= next_guess;
            count <= count + 1;
        end
    end else begin
        out <= guess; // Fallback output if not converged
        valid <= 1'b0; // Stop iterations
    end
end

endmodule

module int_sqrt (
    input signed [15:0] in_0,
    output signed [7:0] out
);
    reg signed [7:0] y;
    reg signed [15:0] x;
    reg [3:0] state;
    reg [3:0] next_state;

    parameter IDLE = 0, INIT = 1, ITERATE = 2, DONE = 3;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            y <= 0;
        end else begin
            state <= next_state;
            if (state == INIT) begin
                y <= in_0 >> 1; // Initial guess
                x <= in_0;
            end else if (state == ITERATE) begin
                if (y * y > x) begin
                    y <= y - 1; // Decrease guess
                end else if ((y + 1) * (y + 1) <= x) begin
                    y <= y + 1; // Increase guess
                end else begin
                    next_state <= DONE; // Converged
                end
            end
        end
    end

    always @(*) begin
        case (state)
            IDLE: next_state = (in_0 >= 0) ? INIT : IDLE;
            INIT: next_state = ITERATE;
            ITERATE: next_state = (y * y <= x && (y + 1) * (y + 1) > x) ? DONE : ITERATE;
            DONE: next_state = DONE; // Stay in DONE state
            default: next_state = IDLE;
        endcase
    end

    assign out = (state == DONE) ? y : 0;

endmodule

