assign pp1 = a[1] ? {b, 1'b0} : 5'b00000;  // Shift left by 1
assign pp2 = a[2] ? {b, 2'b00} : 6'b000000; // Shift left by 2
assign pp3 = a[3] ? {b, 3'b000} : 7'b0000000; // Shift left by 3

// Sum the partial products
assign sum1 = {4'b0000, pp0};  // Align pp0
assign sum2 = {3'b000, pp1, 1'b0}; // Align pp1
assign sum3 = {2'b00, pp2, 2'b00}; // Align pp2
assign sum4 = {1'b0, pp3, 3'b000}; // Align pp3

