        partial_products[1] <= 0;
        partial_products[2] <= 0;
        partial_products[3] <= 0;
        partial_products[4] <= 0;
        partial_products[5] <= 0;
        partial_products[6] <= 0;
        partial_products[7] <= 0;
    end else begin
        a_reg <= a;
        b_reg <= b;
        partial_products[0] <= a_reg & {8{b_reg[0]}};
        partial_products[1] <= a_reg & {8{b_reg[1]}};
        partial_products[2] <= a_reg & {8{b_reg[2]}};
        partial_products[3] <= a_reg & {8{b_reg[3]}};
        partial_products[4] <= a_reg & {8{b_reg[4]}};
        partial_products[5] <= a_reg & {8{b_reg[5]}};
