        sum_stage1 <= partial_products[0] + (partial_products[1] << 1) + 
                      (partial_products[2] << 2) + (partial_products[3] << 3) +
                      (partial_products[4] << 4) + (partial_products[5] << 5) +
                      (partial_products[6] << 6) + (partial_products[7] << 7);
    end
