    input [7:0] a, b,
    output reg [15:0] out
);

    reg [7:0] partial_products[0:7]; // Stage 1: Partial products
    reg [15:0] sum_stage1, sum_stage2; // Stage 2: Accumulated sums
    reg [15:0] final_sum; // Stage 3: Final sum
    integer i;

    // Stage 1: Compute partial products
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 8; i = i + 1) begin
                partial_products[i] <= 8'b0;
            end
        end else begin
            for (i = 0; i < 8; i = i + 1) begin
                partial_products[i] <= a[i] ? b : 8'b0; // Generate partial product
            end
        end
    end

    // Stage 2: Accumulate partial products
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sum_stage1 <= 16'b0;
        end else begin
            sum_stage1 <= sum_stage1 + {8'b0, partial_products[0]};
            sum_stage1 <= sum_stage1 + {7'b0, partial_products[1], 1'b0};
            sum_stage1 <= sum_stage1 + {6'b0, partial_products[2], 2'b0};
            sum_stage1 <= sum_stage1 + {5'b0, partial_products[3], 3'b0};
            sum_stage1 <= sum_stage1 + {4'b0, partial_products[4], 4'b0};
            sum_stage1 <= sum_stage1 + {3'b0, partial_products[5], 5'b0};
            sum_stage1 <= sum_stage1 + {2'b0, partial_products[6], 6'b0};
            sum_stage1 <= sum_stage1 + {1'b0, partial_products[7], 7'b0};
        end
    end

    // Stage 3: Finalize the sum
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            final_sum <= 16'b0;
        end else begin
            final_sum <= sum_stage1;
        end
    end

    // Output the final product
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            out <= 16'b0;
        end else begin
            out <= final_sum;
        end
    end

