reg [15:0] prod [3:0];   // Partial products storage
reg [15:0] sum_stage1;   // Accumulated sum in stage 1
reg [15:0] sum_stage2;   // Accumulated sum in stage 2

integer i;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        y <= 16'b0;
        sum_stage1 <= 16'b0;
        sum_stage2 <= 16'b0;
        for (i = 0; i < 4; i = i + 1) begin
            x_reg[i] <= 8'b0;
            prod[i] <= 16'b0;
        end
    end else begin
        // Shift input samples
        x_reg[0] <= x;
        for (i = 1; i < 4; i = i + 1) begin
            x_reg[i] <= x_reg[i-1];
        end

        // Multiply inputs by coefficients
        prod[0] <= x_reg[0] * coeffs[0];
        prod[1] <= x_reg[1] * coeffs[1];
        prod[2] <= x_reg[2] * coeffs[2];
        prod[3] <= x_reg[3] * coeffs[3];

        // Stage 1 accumulation
        sum_stage1 <= prod[0] + prod[1];

        // Stage 2 accumulation
        sum_stage2 <= sum_stage1 + prod[2];

        // Final output
        y <= sum_stage2 + prod[3];
    end
end

