module compound_interest (
    input [15:0] P,
    input [7:0] r,
    input [7:0] n,
    output reg [31:0] A
);
    reg [31:0] base;
    reg [31:0] result;
    integer i;

    always @* begin
        // Convert r to fixed-point representation
        base = (256 + r); // 1 + r, scaling by 2^8
        result = 1; // Initialize result to 1

        // Calculate (1 + r)^n using successive multiplications
        for (i = 0; i < n; i = i + 1) begin
            result = (result * base) >> 8; // Scale down by 2^8 to maintain precision
        end

        // Calculate A = P * (1 + r)^n
        A = (P * result) >> 8; // Scale down final result by 2^8
    end
endmodule

