module present_value (
    input [15:0] future_amount,
    input [7:0] rate,
    input [7:0] n,
    output reg [15:0] present_value
);

reg [15:0] base_value;
reg [31:0] denominator;
reg [7:0] i;
reg [15:0] power_result;
reg [31:0] temp;

always @(*) begin
    // Step 1: Calculate base_value = 1 + rate/100, scaled by 256
    base_value = (256 + rate * 256 / 100); // 1 is scaled to 256

    // Step 2: Calculate (1 + rate/100)^n
    power_result = 256; // Initialize power_result to 1 (scaled by 256)
    for (i = 0; i < n; i = i + 1) begin
        power_result = (power_result * base_value) >> 8; // Divide by 256 to maintain scaling
    end

    // Step 3: Calculate future_amount / power_result
    // Use fixed-point division
    denominator = power_result; // Denominator is the computed power
    present_value = 0; // Initialize present_value

    // Perform division using iterative subtraction method
    temp = future_amount; // Start with future_amount
    while (temp >= denominator) begin
        temp = temp - denominator;
        present_value = present_value + 1; // Increment present_value
    end

    // Handle overflow if present_value exceeds 16 bits
