module wavelength (
    input [7:0] frequency,   // frequency in MHz
    output [7:0] wavelength  // wavelength in meters
);

    reg [7:0] wavelength_reg;

    always @(*) begin
        if (frequency == 8'b00000000) begin
            wavelength_reg = 8'b00000000; // wavelength = 0 when frequency = 0
        end else begin
            // Perform division: wavelength = c / f, where c = 300
            wavelength_reg = (300 / frequency);
            // Ensure the output is limited to 8 bits
            if (wavelength_reg > 8'hFF) begin
                wavelength_reg = 8'hFF; // Clipping to maximum 8-bit value
            end
        end
    end

    assign wavelength = wavelength_reg;

endmodule

