module heat_index (
    input [7:0] temperature,   // Temperature in Celsius
    input [7:0] humidity,      // Humidity in percentage
    input signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9,    // Quartic T^2*R^2
    output signed [15:0] heat_index // Heat Index in Celsius
);

    wire signed [15:0] T, R;
    wire signed [15:0] C2T, C3R, C4TR, C5T2, C6R2, C7T2R, C8TR2, C9T2R2;
    wire signed [15:0] term_sum;

    assign T = {8'b0, temperature}; // Sign extend temperature to 16 bits
    assign R = {8'b0, humidity};     // Sign extend humidity to 16 bits

    // Calculate each term
    assign C2T = C2 * T;                         // C2 * T
    assign C3R = C3 * R;                         // C3 * R
    assign C4TR = C4 * T * R;                    // C4 * T * R
    assign C5T2 = C5 * T * T;                    // C5 * T^2
    assign C6R2 = C6 * R * R;                    // C6 * R^2
    assign C7T2R = C7 * T * T * R;               // C7 * T^2 * R
    assign C8TR2 = C8 * T * R * R;               // C8 * T * R^2
    assign C9T2R2 = C9 * T * T * R * R;          // C9 * T^2 * R^2

    // Sum all terms to get the heat index
    assign term_sum = C1 + C2T + C3R + C4TR + C5T2 + C6R2 + C7T2R + C8TR2 + C9T2R2;

    assign heat_index = term_sum; // Assign final heat index output

endmodule

module heat_index (
    input [7:0] temperature,   // Temperature in Celsius
    input [7:0] humidity,      // Humidity in percentage
    input signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9,    // Quartic T^2*R^2
    output signed [15:0] heat_index // Heat Index in Celsius
);

