    assign term7 = C7 * T2 * R;        // C7 * T^2 * R
    assign term8 = C8 * T * R2;        // C8 * T * R^2
    assign term9 = C9 * T2 * R2;       // C9 * T^2 * R^2

    // Combine all terms to compute the heat index
    wire signed [31:0] heat_index_temp;
    assign heat_index_temp = term1 + term2 + term3 + term4 + term5 + term6 + term7 + term8 + term9;

    // Assign the final heat index, ensuring it is 16 bits
    assign heat_index = heat_index_temp[15:0]; // Truncate to 16 bits

endmodule

