module solar_radiation_average (
    input [7:0] r0, r1, r2, r3, r4, r5, r6, r7,
    output [7:0] avg_radiation
);

reg [15:0] sum; // 16-bit accumulator to prevent overflow
reg [7:0] average;

always @(*) begin
    sum = r0 + r1 + r2 + r3 + r4 + r5 + r6 + r7; // Compute sum
    average = sum[15:3]; // Right shift by 3 to divide by 8
end

assign avg_radiation = average;

endmodule

